node --input-type=module << 'EOF'
import fs from "fs";
import path from "path";

const load = (name) => {
  const filePath = path.join(process.cwd(), name);
  if (!fs.existsSync(filePath)) return null;
  const env = {};
  for (const line of fs.readFileSync(filePath, "utf8").split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const match = trimmed.match(/^([^=]+)=(.*)$/);
    if (!match) continue;
    const key = match[1].trim();
    let value = match[2].trim();
    if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }
    env[key] = value;
  }
  return env;
};

const files = [".env", ".env.local", ".env.development", ".env.development.local", ".env.production", ".env.production.local"];
const loaded = {};
for (const name of files) loaded[name] = load(name);

const present = files.filter((name) => loaded[name]);
console.log("present_files=" + present.join(","));

const prod = loaded[".env.production.local"] ?? {};
const local = loaded[".env.local"] ?? {};
const dotenv = loaded[".env"] ?? {};
const devLocal = loaded[".env.development.local"] ?? {};
const dev = loaded[".env.development"] ?? {};

const union = new Set([...Object.keys(prod), ...Object.keys(local), ...Object.keys(dotenv), ...Object.keys(devLocal), ...Object.keys(dev)]);

const onlyLocal = [];
const onlyDotenv = [];
const onlyDev = [];
const missingFromProd = [];
const differ = [];
const same = [];

for (const key of [...union].sort()) {
  const inProd = Object.prototype.hasOwnProperty.call(prod, key);
  const inLocal = Object.prototype.hasOwnProperty.call(local, key);
  const inDot = Object.prototype.hasOwnProperty.call(dotenv, key);
  const inDev = Object.prototype.hasOwnProperty.call(dev, key) || Object.prototype.hasOwnProperty.call(devLocal, key);
  if (!inProd && inLocal) onlyLocal.push(key);
  if (!inProd && inDot) onlyDotenv.push(key);
  if (!inProd && inDev) onlyDev.push(key);
  if (!inProd) missingFromProd.push(key);
  if (inProd && inLocal) {
    if (prod[key] === local[key]) same.push(key);
    else differ.push(key);
  }
}

const originOf = (value) => {
  if (!value) return "empty";
  try {
    const url = new URL(value);
    return `${url.protocol}//${url.host}`;
  } catch {
    return "unparsed";
  }
};

const dbClass = (value) => {
  if (!value) return "missing";
  if (value.includes("kshrgedtoxsiotgzrcru")) return "prod-project-ref";
  if (value.includes("supabase")) return "other-supabase";
  if (value.includes("localhost") || value.includes("127.0.0.1")) return "localhost";
  return "other-host";
};

const smtpHost = (value) => {
  if (!value) return "missing";
  try {
    const url = new URL(value);
    return url.hostname;
  } catch {
    return "unparsed";
  }
};

console.log("prod_key_count=" + Object.keys(prod).length);
console.log("local_key_count=" + Object.keys(local).length);
console.log("dotenv_key_count=" + Object.keys(dotenv).length);
console.log("only_in_env_local=" + (onlyLocal.join(",") || "(none)"));
console.log("only_in_dotenv=" + (onlyDotenv.join(",") || "(none)"));
console.log("only_in_dev_files=" + (onlyDev.join(",") || "(none)"));
console.log("shared_same_value_count=" + same.length);
console.log("shared_different_value=" + (differ.join(",") || "(none)"));
console.log("APP_ENV_prod_file=" + (prod.APP_ENV || "missing"));
console.log("APP_ENV_local_file=" + (local.APP_ENV || "missing"));
console.log("NEXT_PUBLIC_APP_URL_prod=" + originOf(prod.NEXT_PUBLIC_APP_URL));
console.log("NEXTAUTH_URL_prod=" + originOf(prod.NEXTAUTH_URL));
console.log("NEXT_PUBLIC_APP_URL_local=" + originOf(local.NEXT_PUBLIC_APP_URL));
console.log("NEXTAUTH_URL_local=" + originOf(local.NEXTAUTH_URL));
console.log("DATABASE_URL_prod=" + dbClass(prod.DATABASE_URL));
console.log("DIRECT_URL_prod=" + dbClass(prod.DIRECT_URL));
console.log("DATABASE_URL_local=" + dbClass(local.DATABASE_URL));
console.log("DIRECT_URL_local=" + dbClass(local.DIRECT_URL));
console.log("DATABASE_URL_dotenv=" + dbClass(dotenv.DATABASE_URL));
console.log("DIRECT_URL_dotenv=" + dbClass(dotenv.DIRECT_URL));
console.log("EMAIL_SERVER_prod_host=" + smtpHost(prod.EMAIL_SERVER));
console.log("EMAIL_SERVER_local_host=" + smtpHost(local.EMAIL_SERVER));
console.log("analytics_prod=" + (prod.NEXT_PUBLIC_ANALYTICS_PROVIDER || "unset"));
console.log("analytics_local=" + (local.NEXT_PUBLIC_ANALYTICS_PROVIDER || "unset"));

const nonempty = (env, key) => Boolean(env[key] && env[key].trim());
const backendKeys = [
  "APP_ENV","NEXT_PUBLIC_APP_URL","NEXTAUTH_URL","NEXTAUTH_SECRET","DATABASE_URL","DIRECT_URL",
  "EMAIL_SERVER","EMAIL_FROM","ADMIN_LOGIN_ALERT_EMAIL","NEXT_PUBLIC_ANALYTICS_PROVIDER","CRON_SECRET",
  "INDEXNOW_KEY","SENTRY_DSN","NEXT_PUBLIC_SENTRY_DSN","SENTRY_ORG","SENTRY_PROJECT","SENTRY_AUTH_TOKEN",
  "CREEM_API_KEY","CREEM_PRODUCT_ID","CREEM_WEBHOOK_SECRET","CREEM_CHECKOUT_DISCOUNT_CODE","CREEM_CHECKOUT_DISCOUNT_EMAILS",
  "CREEM_CHECKOUT_CUSTOM_PRICE_CENTS","STRIPE_SECRET_KEY","STRIPE_WEBHOOK_SECRET","GEMINI_API_KEY","GROQ_API_KEY",
  "UPSTASH_REDIS_REST_URL","UPSTASH_REDIS_REST_TOKEN"
];
for (const key of backendKeys) {
  const p = nonempty(prod, key) ? "set" : "empty";
  const l = nonempty(local, key) ? "set" : "empty";
  const d = nonempty(dotenv, key) ? "set" : "empty";
  console.log(`key ${key} prod=${p} local=${l} dotenv=${d}`);
}
EOF

