import fs from "fs";
const text = fs.readFileSync(".env.production.local", "utf8");
const env = {};
for (const line of text.split("\n")) {
  const trimmed = line.trim();
  if (!trimmed || trimmed.startsWith("#")) continue;
  const match = trimmed.match(/^([^=]+)=(.*)$/);
  if (!match) continue;
  let value = match[2].trim();
  if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) value = value.slice(1, -1);
  env[match[1].trim()] = value;
}
const prefix = (value, n) => value ? value.slice(0, n) : "empty";
const stripeMode = (value) => {
  if (!value) return "empty";
  if (value.startsWith("sk_live_")) return "live";
  if (value.startsWith("sk_test_")) return "test";
  return "other";
};
const whsec = (value) => value ? (value.startsWith("whsec_") ? "whsec-set" : "set-other") : "empty";
const creem = (value) => {
  if (!value) return "empty";
  if (/test/i.test(value.slice(0, 12))) return "prefix-looks-test";
  if (/live/i.test(value.slice(0, 12))) return "prefix-looks-live";
  return "set";
};
console.log("stripe_secret_mode=" + stripeMode(env.STRIPE_SECRET_KEY));
console.log("stripe_webhook=" + whsec(env.STRIPE_WEBHOOK_SECRET));
console.log("creem_api=" + creem(env.CREEM_API_KEY));
console.log("creem_product_prefix=" + prefix(env.CREEM_PRODUCT_ID, 5));
console.log("gemini=" + (env.GEMINI_API_KEY ? "set" : "empty"));
console.log("groq=" + (env.GROQ_API_KEY ? "set" : "empty"));
console.log("email_from_same_shape=" + (env.EMAIL_FROM?.includes("@") ? "has-at" : "missing"));
